// Package gen generates the protobus service bindings for .proto files: for
// every service, a server interface with its registration function and a
// typed client. Message types come from protoc-gen-go; this package emits
// only the *_protobus.pb.go files beside them.
package gen

import (
	"fmt"
	"strings"

	"google.golang.org/protobuf/compiler/protogen"

	"github.com/ArielLaub/protobus-go/v2/internal/version"
)

// Version is stamped into generated files.
const Version = version.Version

// Options tune the generated names.
type Options struct {
	// Infix is inserted after the service name in every generated identifier
	// (with "Bus": CalcBusServer, RegisterCalcBusServer, NewCalcBusClient),
	// so protobus bindings can live in the same package as gRPC ones.
	Infix string
}

const (
	// protobusImport is imported under an explicit name: protogen would name
	// it after its last path element, "v2".
	protobusImport = "github.com/ArielLaub/protobus-go/v2"
)

// GenerateFile writes the bindings for file's services. It returns nil when
// the file declares none.
func GenerateFile(gen *protogen.Plugin, file *protogen.File) (*protogen.GeneratedFile, error) {
	return GenerateFileWith(gen, file, Options{})
}

// GenerateFileWith is GenerateFile with options.
func GenerateFileWith(gen *protogen.Plugin, file *protogen.File, opts Options) (*protogen.GeneratedFile, error) {
	if len(file.Services) == 0 {
		return nil, nil
	}
	for _, svc := range file.Services {
		for _, m := range svc.Methods {
			if m.Desc.IsStreamingClient() {
				return nil, fmt.Errorf("%s: protobus does not support client streaming (method %s)",
					file.Desc.Path(), m.Desc.FullName())
			}
		}
		if err := checkNameClashes(svc); err != nil {
			return nil, fmt.Errorf("%s: %w", file.Desc.Path(), err)
		}
	}

	g := gen.NewGeneratedFile(file.GeneratedFilenamePrefix+"_protobus.pb.go", file.GoImportPath)
	g.P("// Code generated by protoc-gen-go-protobus. DO NOT EDIT.")
	g.P("// versions:")
	g.P("// - protoc-gen-go-protobus v", Version)
	g.P("// source: ", file.Desc.Path())
	g.P()
	g.P("package ", file.GoPackageName)
	g.P()
	// One import block, written out rather than collected by protogen, so
	// protobus gets its proper name. protogen still imports message types
	// from other Go packages, as a second block when needed.
	var unary, streaming bool
	for _, svc := range file.Services {
		for _, m := range svc.Methods {
			if m.Desc.IsStreamingServer() {
				streaming = true
			} else {
				unary = true
			}
		}
	}
	g.P("import (")
	g.P(`"context"`)
	if streaming {
		g.P(`"iter"`)
	}
	g.P()
	if unary {
		g.P(`"google.golang.org/protobuf/proto"`)
	}
	g.P()
	g.P("protobus ", fmt.Sprintf("%q", protobusImport))
	g.P(")")
	g.P()
	// The generated code targets these protobus APIs; fail the build early
	// against an incompatible library rather than late with odd errors.
	g.P("// This is a compile-time assertion that the protobus-go library is new")
	g.P("// enough for, and still supports, this generated code.")
	g.P("const _ = protobus.SupportPackageIsVersion1")
	g.P()
	for _, svc := range file.Services {
		genService(g, svc, opts)
	}
	return g, nil
}

func checkNameClashes(svc *protogen.Service) error {
	seen := map[string]string{}
	for _, m := range svc.Methods {
		if prev, dup := seen[m.GoName]; dup {
			return fmt.Errorf("methods %s and %s of %s both map to the Go name %s",
				prev, m.Desc.Name(), svc.Desc.FullName(), m.GoName)
		}
		seen[m.GoName] = string(m.Desc.Name())
	}
	return nil
}

func deprecated(g *protogen.GeneratedFile, d bool) {
	if d {
		g.P("//")
		g.P("// Deprecated: Do not use.")
	}
}

func comment(g *protogen.GeneratedFile, c protogen.Comments, fallback string) {
	text := strings.TrimSpace(string(c))
	if text == "" {
		g.P("// ", fallback)
		return
	}
	for _, line := range strings.Split(text, "\n") {
		// protoc keeps the space after "//" in each line; keep exactly one.
		line = strings.TrimPrefix(line, " ")
		g.P(strings.TrimRight("// "+line, " "))
	}
}

func genService(g *protogen.GeneratedFile, svc *protogen.Service, opts Options) {
	name := svc.GoName + opts.Infix
	full := string(svc.Desc.FullName())
	serverIface := name + "Server"
	clientIface := name + "Client"
	unimpl := "Unimplemented" + serverIface
	descVar := name + "_ServiceDesc"
	nameConst := name + "_ServiceName"
	dep := svc.Desc.Options() != nil && isDeprecated(svc)

	g.P("// ", nameConst, " is the fully-qualified name of the ", full, " service.")
	g.P("const ", nameConst, " = ", fmt.Sprintf("%q", full))
	g.P()

	// ---- server ----
	comment(g, svc.Comments.Leading, serverIface+" is the server API for the "+full+" service.")
	g.P("//")
	g.P("// Implementations should embed ", unimpl, " so that adding a method to the")
	g.P("// service does not break them: an unimplemented method answers its caller")
	g.P("// with a PROTOCOL_ERROR.")
	deprecated(g, dep)
	g.P("type ", serverIface, " interface {")
	for _, m := range svc.Methods {
		comment(g, m.Comments.Leading, m.GoName+" serves the "+string(m.Desc.Name())+" method.")
		deprecated(g, isMethodDeprecated(m))
		g.P(serverSignature(g, m))
	}
	g.P("}")
	g.P()

	g.P("// ", unimpl, " answers every method with protobus.ErrUnimplemented.")
	g.P("type ", unimpl, " struct{}")
	g.P()
	for _, m := range svc.Methods {
		g.P("func (", unimpl, ") ", serverSignature(g, m), " {")
		if m.Desc.IsStreamingServer() {
			g.P("return ", "protobus.ErrUnimplemented")
		} else {
			g.P("return nil, ", "protobus.ErrUnimplemented")
		}
		g.P("}")
		g.P()
	}

	g.P("// ", descVar, " describes the ", full, " service for protobus.Bus.Register.")
	g.P("var ", descVar, " = ", "protobus.ServiceDesc", "{")
	g.P("ServiceName: ", nameConst, ",")
	g.P("HandlerType: (*", serverIface, ")(nil),")
	g.P("Methods: []", "protobus.MethodDesc", "{")
	for _, m := range svc.Methods {
		if m.Desc.IsStreamingServer() {
			continue
		}
		g.P("{")
		g.P("MethodName: ", fmt.Sprintf("%q", m.Desc.Name()), ",")
		in := g.QualifiedGoIdent(m.Input.GoIdent)
		g.P("Handler: func(srv any, ctx context.Context, dec protobus.DecodeFunc, interceptor protobus.UnaryServerInterceptor) (proto.Message, error) {")
		g.P("in := new(", in, ")")
		g.P("if err := dec(in); err != nil {")
		g.P("return nil, err")
		g.P("}")
		g.P("if interceptor == nil {")
		g.P("return srv.(", serverIface, ").", m.GoName, "(ctx, in)")
		g.P("}")
		g.P("info := &protobus.UnaryServerInfo{Server: srv, FullMethod: ", fmt.Sprintf("%q", m.Desc.FullName()), "}")
		g.P("return interceptor(ctx, in, info, func(ctx context.Context, req proto.Message) (proto.Message, error) {")
		g.P("return srv.(", serverIface, ").", m.GoName, "(ctx, req.(*", in, "))")
		g.P("})")
		g.P("},")
		g.P("},")
	}
	g.P("},")
	g.P("Streams: []", "protobus.StreamDesc", "{")
	for _, m := range svc.Methods {
		if !m.Desc.IsStreamingServer() {
			continue
		}
		g.P("{")
		g.P("MethodName: ", fmt.Sprintf("%q", m.Desc.Name()), ",")
		in := g.QualifiedGoIdent(m.Input.GoIdent)
		out := g.QualifiedGoIdent(m.Output.GoIdent)
		g.P("Handler: func(srv any, ctx context.Context, dec protobus.DecodeFunc, stream protobus.RawServerStream, interceptor protobus.StreamServerInterceptor) error {")
		g.P("in := new(", in, ")")
		g.P("if err := dec(in); err != nil {")
		g.P("return err")
		g.P("}")
		g.P("if interceptor == nil {")
		g.P("return srv.(", serverIface, ").", m.GoName, "(ctx, in, protobus.NewServerStream[*", out, "](stream))")
		g.P("}")
		g.P("info := &protobus.StreamServerInfo{Server: srv, FullMethod: ", fmt.Sprintf("%q", m.Desc.FullName()), "}")
		g.P("return interceptor(ctx, in, stream, info, func(ctx context.Context, req proto.Message, stream protobus.RawServerStream) error {")
		g.P("return srv.(", serverIface, ").", m.GoName, "(ctx, req.(*", in, "), protobus.NewServerStream[*", out, "](stream))")
		g.P("})")
		g.P("},")
		g.P("},")
	}
	g.P("},")
	g.P("}")
	g.P()

	g.P("// Register", serverIface, " prepares srv to serve ", full, " on bus. Call Start on")
	g.P("// the returned service (or pass it to protobus.Run) to begin serving.")
	deprecated(g, dep)
	g.P("func Register", serverIface, "(bus *", "protobus.Bus", ", srv ", serverIface, ", opts ...",
		"protobus.ServiceOption", ") (*", "protobus.Service", ", error) {")
	g.P("return bus.Register(&", descVar, ", srv, opts...)")
	g.P("}")
	g.P()

	// ---- client ----
	comment(g, svc.Comments.Leading, clientIface+" is the client API for the "+full+" service.")
	deprecated(g, dep)
	g.P("type ", clientIface, " interface {")
	for _, m := range svc.Methods {
		comment(g, m.Comments.Leading, m.GoName+" calls the "+string(m.Desc.Name())+" method.")
		deprecated(g, isMethodDeprecated(m))
		g.P(clientSignature(g, m))
	}
	g.P("}")
	g.P()

	impl := lowerFirst(name) + "Client"
	g.P("type ", impl, " struct {")
	g.P("c *", "protobus.Client")
	g.P("}")
	g.P()
	g.P("// New", clientIface, " returns a client for ", full, ". Pass protobus.WithInstance")
	g.P("// to address a named instance of the service.")
	deprecated(g, dep)
	g.P("func New", clientIface, "(bus *", "protobus.Bus", ", opts ...", "protobus.ClientOption",
		") ", clientIface, " {")
	g.P("return &", impl, "{c: ", "protobus.NewClient", "(bus, ", nameConst, ", opts...)}")
	g.P("}")
	g.P()
	for _, m := range svc.Methods {
		g.P("func (c *", impl, ") ", clientSignature(g, m), " {")
		method := fmt.Sprintf("%q", m.Desc.Name())
		if m.Desc.IsStreamingServer() {
			g.P("return ", "protobus.Stream", "[*", g.QualifiedGoIdent(m.Output.GoIdent), "](ctx, c.c, ",
				method, ", in, opts...)")
		} else {
			g.P("out := new(", g.QualifiedGoIdent(m.Output.GoIdent), ")")
			g.P("if err := c.c.Invoke(ctx, ", method, ", in, out, opts...); err != nil {")
			g.P("return nil, err")
			g.P("}")
			g.P("return out, nil")
		}
		g.P("}")
		g.P()
	}
}

func serverSignature(g *protogen.GeneratedFile, m *protogen.Method) string {
	ctx := "context.Context"
	in := g.QualifiedGoIdent(m.Input.GoIdent)
	out := g.QualifiedGoIdent(m.Output.GoIdent)
	if m.Desc.IsStreamingServer() {
		stream := "protobus.ServerStream"
		return fmt.Sprintf("%s(%s, *%s, %s[*%s]) error", m.GoName, ctx, in, stream, out)
	}
	return fmt.Sprintf("%s(%s, *%s) (*%s, error)", m.GoName, ctx, in, out)
}

func clientSignature(g *protogen.GeneratedFile, m *protogen.Method) string {
	ctx := "context.Context"
	in := g.QualifiedGoIdent(m.Input.GoIdent)
	out := g.QualifiedGoIdent(m.Output.GoIdent)
	if m.Desc.IsStreamingServer() {
		seq := "iter.Seq2"
		opt := "protobus.StreamOption"
		return fmt.Sprintf("%s(ctx %s, in *%s, opts ...%s) %s[*%s, error]", m.GoName, ctx, in, opt, seq, out)
	}
	opt := "protobus.CallOption"
	return fmt.Sprintf("%s(ctx %s, in *%s, opts ...%s) (*%s, error)", m.GoName, ctx, in, opt, out)
}

func lowerFirst(s string) string {
	if s == "" {
		return s
	}
	return strings.ToLower(s[:1]) + s[1:]
}
